import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o,af as n}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const q=JSON.parse('{"title":"上下文工程深度解析：从提示词优化到注意力预算管理","description":"","frontmatter":{},"headers":[],"relativePath":"zh/ai-tools/context-engineering-deep-dive.md","filePath":"zh/ai-tools/context-engineering-deep-dive.md","lastUpdated":1780929478000}'),r={name:"zh/ai-tools/context-engineering-deep-dive.md"};function i(l,t,s,h,d,p){return o(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="上下文工程深度解析-从提示词优化到注意力预算管理" tabindex="-1">上下文工程深度解析：从提示词优化到注意力预算管理 <a class="header-anchor" href="#上下文工程深度解析-从提示词优化到注意力预算管理" aria-label="Permalink to &quot;上下文工程深度解析：从提示词优化到注意力预算管理&quot;">​</a></h1><blockquote><p>学习来源：<a href="https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents" target="_blank" rel="noreferrer">Anthropic - Effective Context Engineering for AI Agents</a><br> 阅读时间：2026-04-12<br> 标签：#上下文工程 #AI-Agent #注意力机制 #Claude</p></blockquote><hr><h2 id="一、核心认知升级-从-写好提示词-到-管理注意力预算" tabindex="-1">一、核心认知升级：从&quot;写好提示词&quot;到&quot;管理注意力预算&quot; <a class="header-anchor" href="#一、核心认知升级-从-写好提示词-到-管理注意力预算" aria-label="Permalink to &quot;一、核心认知升级：从&quot;写好提示词&quot;到&quot;管理注意力预算&quot;&quot;">​</a></h2><h3 id="_1-1-范式转移的本质" tabindex="-1">1.1 范式转移的本质 <a class="header-anchor" href="#_1-1-范式转移的本质" aria-label="Permalink to &quot;1.1 范式转移的本质&quot;">​</a></h3><p>传统的**提示工程（Prompt Engineering）<strong>关注的是&quot;如何写好提示词的词汇和短语&quot;，而</strong>上下文工程（Context Engineering）**要回答的是更根本的问题：</p><blockquote><p><strong>&quot;什么样的上下文配置最有可能引导模型产生期望的行为？&quot;</strong></p></blockquote><p>这个转变背后的驱动力是 Agent 系统的兴起。当 LLM 从单轮问答演进到多轮推理、从独立任务延伸到长时域操作时，工程师面对的不再是&quot;写一个好提示&quot;，而是&quot;在不断演化的信息宇宙中，持续筛选和优化进入 context window 的 token 集合&quot;。</p><h3 id="_1-2-上下文工程的定义" tabindex="-1">1.2 上下文工程的定义 <a class="header-anchor" href="#_1-2-上下文工程的定义" aria-label="Permalink to &quot;1.2 上下文工程的定义&quot;">​</a></h3><p><strong>上下文 = LLM 采样时包含的所有 token 集合</strong></p><p>上下文工程的目标：<strong>在 LLM 固有约束条件下，最大化这些 token 的效用，以持续达成期望结果。</strong></p><p>关键洞察：<strong>上下文工程是迭代的</strong>——每次决定向模型传递什么信息时，都会发生一次上下文 curation phase，这与写一个静态提示词有本质区别。</p><hr><h2 id="二、注意力预算-llm-的稀缺资源" tabindex="-1">二、注意力预算：LLM 的稀缺资源 <a class="header-anchor" href="#二、注意力预算-llm-的稀缺资源" aria-label="Permalink to &quot;二、注意力预算：LLM 的稀缺资源&quot;">​</a></h2><h3 id="_2-1-为什么上下文是有限资源" tabindex="-1">2.1 为什么上下文是有限资源 <a class="header-anchor" href="#_2-1-为什么上下文是有限资源" aria-label="Permalink to &quot;2.1 为什么上下文是有限资源&quot;">​</a></h3><p>Anthropic 明确指出了一个反直觉但极其重要的观察：<strong>LLM 和人类一样，在某个临界点后会失去焦点或产生困惑。</strong></p><p>这源于两个技术原因：</p><h4 id="transformer-架构的-n2-复杂度" tabindex="-1">Transformer 架构的 n² 复杂度 <a class="header-anchor" href="#transformer-架构的-n2-复杂度" aria-label="Permalink to &quot;Transformer 架构的 n² 复杂度&quot;">​</a></h4><p>LLM 基于 Transformer 架构，每个 token 可以attend到上下文中的所有其他 token。对于 n 个token，存在 n² 个成对关系。随着上下文增长，模型捕捉这些成对关系的能力被&quot;摊薄&quot;。</p><h4 id="训练数据分布偏差" tabindex="-1">训练数据分布偏差 <a class="header-anchor" href="#训练数据分布偏差" aria-label="Permalink to &quot;训练数据分布偏差&quot;">​</a></h4><p>模型在训练数据中，短序列的出现频率远高于长序列。这意味着：</p><ul><li>模型在处理长上下文时经验不足</li><li>专门处理上下文级依赖的参数使用不够充分</li></ul><h3 id="_2-2-上下文腐烂-context-rot-现象" tabindex="-1">2.2 上下文腐烂（Context Rot）现象 <a class="header-anchor" href="#_2-2-上下文腐烂-context-rot-现象" aria-label="Permalink to &quot;2.2 上下文腐烂（Context Rot）现象&quot;">​</a></h3><p>研究中的&quot;大海捞针&quot;（needle-in-a-haystack）基准测试揭示了<strong>上下文腐烂</strong>现象：随着 context window 中 token 数量的增加，模型准确回忆上下文中信息的能力下降。</p><p>虽然不同模型的衰减程度不同，但这个特征在所有模型中都会出现。</p><h3 id="_2-3-核心原则" tabindex="-1">2.3 核心原则 <a class="header-anchor" href="#_2-3-核心原则" aria-label="Permalink to &quot;2.3 核心原则&quot;">​</a></h3><blockquote><p><strong>上下文必须被视为一种有限资源，具有边际效益递减的特性。</strong></p><p>每个新引入的 token 都会以某种程度消耗注意力预算。因此，需要精心 curation 可用于 LLM 的 token 集合。</p></blockquote><p><strong>类比人类工作记忆</strong>：人类有有限的工作记忆容量，LLM 同样有&quot;注意力预算&quot;。这不仅是技术约束，更是设计原则——你需要像管理人类认知负荷一样管理模型的上下文。</p><hr><h2 id="三、有效上下文的组成解剖" tabindex="-1">三、有效上下文的组成解剖 <a class="header-anchor" href="#三、有效上下文的组成解剖" aria-label="Permalink to &quot;三、有效上下文的组成解剖&quot;">​</a></h2><h3 id="_3-1-系统提示词-system-prompts" tabindex="-1">3.1 系统提示词（System Prompts） <a class="header-anchor" href="#_3-1-系统提示词-system-prompts" aria-label="Permalink to &quot;3.1 系统提示词（System Prompts）&quot;">​</a></h3><p>系统提示词应极度清晰，使用简单、直接的语言，并在&quot;正确的高度&quot;呈现 ideas。</p><h4 id="两种常见的失败模式" tabindex="-1">两种常见的失败模式 <a class="header-anchor" href="#两种常见的失败模式" aria-label="Permalink to &quot;两种常见的失败模式&quot;">​</a></h4><table tabindex="0"><thead><tr><th>极端</th><th>表现</th><th>问题</th></tr></thead><tbody><tr><td><strong>过度具体</strong></td><td>在 prompt 中硬编码复杂的 if-else 逻辑</td><td>脆弱性增加，维护复杂度随时间增长</td></tr><tr><td><strong>过度抽象</strong></td><td>提供模糊、高层次的指导，假设存在&quot;共享上下文&quot;</td><td>无法给 LLM 提供具体的行为信号</td></tr></tbody></table><h4 id="正确高度-的平衡点" tabindex="-1">&quot;正确高度&quot;的平衡点 <a class="header-anchor" href="#正确高度-的平衡点" aria-label="Permalink to &quot;&quot;正确高度&quot;的平衡点&quot;">​</a></h4><p><strong>最佳实践</strong>：足够具体以有效引导行为，同时足够灵活以提供强有力的启发式规则。</p><blockquote><p>不是告诉 Agent &quot;在这种情况下怎么做&quot;，而是告诉它&quot;遇到问题时如何思考&quot;。</p></blockquote><h4 id="结构化建议" tabindex="-1">结构化建议 <a class="header-anchor" href="#结构化建议" aria-label="Permalink to &quot;结构化建议&quot;">​</a></h4><p>Anthropic 推荐将系统提示词组织成清晰的部分：</p><ul><li><code>&lt;background_information&gt;</code> - 背景信息</li><li><code>&lt;instructions&gt;</code> - 指令</li><li><code>## Tool guidance</code> - 工具指导</li><li><code>## Output description</code> - 输出描述</li></ul><p>使用 XML 标签或 Markdown 标题来分隔这些部分。不过，随着模型能力提升，具体的格式要求可能变得越来越不重要。</p><h4 id="最小化原则" tabindex="-1">最小化原则 <a class="header-anchor" href="#最小化原则" aria-label="Permalink to &quot;最小化原则&quot;">​</a></h4><p><strong>核心原则</strong>：找到完整描述期望行为所需的最小信息集。</p><blockquote><p>&quot;minimal does not necessarily mean short&quot; — 最小化不意味着简短</p></blockquote><p><strong>推荐方法</strong>：先用最小化提示测试最好的模型，然后根据发现的失败模式逐步添加示例和指令。</p><h3 id="_3-2-工具-tools" tabindex="-1">3.2 工具（Tools） <a class="header-anchor" href="#_3-2-工具-tools" aria-label="Permalink to &quot;3.2 工具（Tools）&quot;">​</a></h3><p>工具定义了 Agent 与其信息/行动空间的契约，因此极其重要。</p><h4 id="工具设计的核心原则" tabindex="-1">工具设计的核心原则 <a class="header-anchor" href="#工具设计的核心原则" aria-label="Permalink to &quot;工具设计的核心原则&quot;">​</a></h4><ol><li><strong>Token 高效</strong> — 返回的信息应在 token 使用上高效</li><li><strong>行为引导高效</strong> — 鼓励高效的 Agent 行为模式</li><li><strong>自包含</strong> — 类似良好设计的代码库，工具应该是自包含的</li><li><strong>错误鲁棒</strong> — 对错误有良好的处理</li><li><strong>用途清晰</strong> — 工具的预期用途必须极其清晰</li></ol><h4 id="最常见的失败模式" tabindex="-1">最常见的失败模式 <a class="header-anchor" href="#最常见的失败模式" aria-label="Permalink to &quot;最常见的失败模式&quot;">​</a></h4><p><strong>工具集合过于臃肿</strong> — 覆盖过多功能或导致关于&quot;使用哪个工具&quot;的模糊决策点。</p><blockquote><p>如果一个人类工程师无法明确说出在给定情况下应该使用哪个工具，就不能期望 AI Agent 做得更好。</p></blockquote><h4 id="最小可行工具集" tabindex="-1">最小可行工具集 <a class="header-anchor" href="#最小可行工具集" aria-label="Permalink to &quot;最小可行工具集&quot;">​</a></h4><p>精简工具集不仅提高决策清晰度，还带来更可靠的长期维护和长交互中的上下文修剪。</p><h3 id="_3-3-示例-few-shot-prompting" tabindex="-1">3.3 示例（Few-shot Prompting） <a class="header-anchor" href="#_3-3-示例-few-shot-prompting" aria-label="Permalink to &quot;3.3 示例（Few-shot Prompting）&quot;">​</a></h3><p>示例是 AI 工程中经久不衰的最佳实践，但常见错误是：</p><p><strong>不推荐</strong>：在 prompt 中塞入大量边缘案例，试图穷举所有规则</p><p><strong>推荐</strong>：精心 curation 一组多样化、典范的示例（canonical examples），有效展示 Agent 的期望行为</p><blockquote><p>对于 LLM，示例是&quot;价值千言的图片&quot;（Examples are the &quot;pictures&quot; worth a thousand words for an LLM）</p></blockquote><hr><h2 id="四、上下文检索策略-just-in-time-vs-预推理检索" tabindex="-1">四、上下文检索策略：Just-in-Time vs 预推理检索 <a class="header-anchor" href="#四、上下文检索策略-just-in-time-vs-预推理检索" aria-label="Permalink to &quot;四、上下文检索策略：Just-in-Time vs 预推理检索&quot;">​</a></h2><h3 id="_4-1-两种范式的对比" tabindex="-1">4.1 两种范式的对比 <a class="header-anchor" href="#_4-1-两种范式的对比" aria-label="Permalink to &quot;4.1 两种范式的对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>方式</th><th>优势</th><th>劣势</th></tr></thead><tbody><tr><td><strong>预推理时间检索</strong></td><td>在推理前预处理所有相关数据</td><td>速度快</td><td>可能包含不相关信息，造成上下文污染</td></tr><tr><td><strong>Just-in-Time</strong></td><td>维护轻量级标识符，运行时动态加载数据</td><td>上下文更精准，避免过时索引</td><td>运行时探索较慢</td></tr></tbody></table><h3 id="_4-2-just-in-time-的认知映射" tabindex="-1">4.2 Just-in-Time 的认知映射 <a class="header-anchor" href="#_4-2-just-in-time-的认知映射" aria-label="Permalink to &quot;4.2 Just-in-Time 的认知映射&quot;">​</a></h3><p>这种模式实际上是在模仿人类认知：</p><blockquote><p>人类不会记住整个语料库，而是引入外部组织和索引系统（文件系统、收件箱、书签）来按需检索相关信息。</p></blockquote><p><strong>Just-in-Time 策略的核心元素</strong>：</p><ul><li>维护轻量级标识符（文件路径、存储查询、网页链接等）</li><li>通过工具在运行时动态加载数据到上下文</li></ul><h3 id="_4-3-元数据的价值" tabindex="-1">4.3 元数据的价值 <a class="header-anchor" href="#_4-3-元数据的价值" aria-label="Permalink to &quot;4.3 元数据的价值&quot;">​</a></h3><p>文件路径、文件夹层次结构、命名约定、时间戳——这些元数据都为 Agent 提供了重要信号，帮助理解如何使用信息。</p><p><strong>示例</strong>：在文件系统中：</p><ul><li><code>tests/test_utils.py</code> 中的 <code>test_utils.py</code> 与 <code>src/core_logic/test_utils.py</code> 传达了不同的用途</li><li>文件大小暗示复杂度</li><li>时间戳可以作为相关性的代理</li></ul><h3 id="_4-4-渐进式发现-progressive-disclosure" tabindex="-1">4.4 渐进式发现（Progressive Disclosure） <a class="header-anchor" href="#_4-4-渐进式发现-progressive-disclosure" aria-label="Permalink to &quot;4.4 渐进式发现（Progressive Disclosure）&quot;">​</a></h3><p>让 Agent 自主导航和检索数据也实现了<strong>渐进式发现</strong>——通过探索逐步发现相关上下文。</p><p>每一轮交互产生指导下一决策的上下文：</p><ul><li>文件大小 → 复杂度</li><li>命名约定 → 用途</li><li>时间戳 → 相关性</li></ul><p>Agent 可以层层构建理解，只在 Working Memory 中维护必要的信息，并利用笔记策略进行额外持久化。</p><h3 id="_4-5-混合策略" tabindex="-1">4.5 混合策略 <a class="header-anchor" href="#_4-5-混合策略" aria-label="Permalink to &quot;4.5 混合策略&quot;">​</a></h3><p>最有效的 Agent 可能采用<strong>混合策略</strong>：</p><ul><li>某些数据预先检索以提高速度</li><li>在需要时进行自主探索</li></ul><p><strong>典型案例：Claude Code</strong></p><ul><li><code>CLAUDE.md</code> 文件被预先放入上下文</li><li><code>glob</code> 和 <code>grep</code> 等原语允许 Agent 实时导航环境并按需检索文件</li></ul><p>对于动态内容较少的场景（如法律或财务工作），混合策略可能更适用。</p><hr><h2 id="五、长时域任务的上下文工程" tabindex="-1">五、长时域任务的上下文工程 <a class="header-anchor" href="#五、长时域任务的上下文工程" aria-label="Permalink to &quot;五、长时域任务的上下文工程&quot;">​</a></h2><p>当任务横跨数十分钟到数小时的连续工作时（如大型代码库迁移或综合研究项目），Agent 需要专门技术来绕过 context window 限制。</p><h3 id="_5-1-压缩-compaction" tabindex="-1">5.1 压缩（Compaction） <a class="header-anchor" href="#_5-1-压缩-compaction" aria-label="Permalink to &quot;5.1 压缩（Compaction）&quot;">​</a></h3><p><strong>压缩 = 将接近 context window 限制的对话总结，用摘要重新初始化新的上下文窗口。</strong></p><h4 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h4><p>在 Claude Code 中实现方式：</p><ol><li>将消息历史传给模型进行总结和压缩</li><li>模型保留：架构决策、未解决的 bug、实现细节</li><li>模型丢弃：冗余的工具输出或消息</li></ol><p>Agent 然后用这个压缩后的上下文继续工作，加上最近访问的 5 个文件。</p><h4 id="压缩的艺术" tabindex="-1">压缩的艺术 <a class="header-anchor" href="#压缩的艺术" aria-label="Permalink to &quot;压缩的艺术&quot;">​</a></h4><p>压缩的艺术在于<strong>选择保留什么、丢弃什么</strong>——过度激进的压缩可能导致微妙但关键上下文的丢失。</p><blockquote><p>最安全的轻量级压缩形式之一：清除工具调用和结果。一旦工具在消息历史深处被调用，Agent 为什么需要再次看到原始结果？</p></blockquote><h4 id="实施建议" tabindex="-1">实施建议 <a class="header-anchor" href="#实施建议" aria-label="Permalink to &quot;实施建议&quot;">​</a></h4><ol><li>先最大化召回率，确保压缩提示捕获轨迹中的每条相关信息</li><li>然后迭代提高精确度，消除多余内容</li></ol><h3 id="_5-2-结构化笔记-structured-note-taking-agentic-memory" tabindex="-1">5.2 结构化笔记（Structured Note-taking / Agentic Memory） <a class="header-anchor" href="#_5-2-结构化笔记-structured-note-taking-agentic-memory" aria-label="Permalink to &quot;5.2 结构化笔记（Structured Note-taking / Agentic Memory）&quot;">​</a></h3><p><strong>核心思想</strong>：Agent 定期将笔记写入持久化内存（context window 之外），后续再拉回上下文。</p><h4 id="典型应用" tabindex="-1">典型应用 <a class="header-anchor" href="#典型应用" aria-label="Permalink to &quot;典型应用&quot;">​</a></h4><ul><li>Claude Code 创建待办列表</li><li>自定义 Agent 维护 <code>NOTES.md</code> 文件</li></ul><h4 id="超越编码的案例" tabindex="-1">超越编码的案例 <a class="header-anchor" href="#超越编码的案例" aria-label="Permalink to &quot;超越编码的案例&quot;">​</a></h4><p><a href="https://www.twitch.tv/claudeplayspokemon" target="_blank" rel="noreferrer">Claude 玩宝可梦</a> 展示了记忆如何转变 Agent 能力：</p><ul><li>跨数千游戏步骤维护精确计数（&quot;过去 1234 步我一直在 Route 1 训练宝可梦，Pikachu 已获得 8 级，目标是 10 级&quot;）</li><li>无需提示，自行开发探索区域地图</li><li>记住已解锁的关键成就</li><li>维护战斗策略笔记</li></ul><p>上下文重置后，Agent 读取自己的笔记，继续数小时训练或地牢探索。</p><h4 id="anthropic-的-memory-tool" tabindex="-1">Anthropic 的 Memory Tool <a class="header-anchor" href="#anthropic-的-memory-tool" aria-label="Permalink to &quot;Anthropic 的 Memory Tool&quot;">​</a></h4><p>作为 Sonnet 4.5 发布的一部分，Anthropic 发布了基于文件的 Memory Tool（公开 beta），使 Agent 更容易通过文件系存储和查询 context window 之外的信息。</p><h3 id="_5-3-子-agent-架构-sub-agent-architectures" tabindex="-1">5.3 子 Agent 架构（Sub-agent Architectures） <a class="header-anchor" href="#_5-3-子-agent-架构-sub-agent-architectures" aria-label="Permalink to &quot;5.3 子 Agent 架构（Sub-agent Architectures）&quot;">​</a></h3><p><strong>核心思想</strong>：不再让一个 Agent 维护整个项目的状态，而是使用专用子 Agent 处理专注任务。</p><h4 id="架构模式" tabindex="-1">架构模式 <a class="header-anchor" href="#架构模式" aria-label="Permalink to &quot;架构模式&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主 Agent（协调者）</span></span>
<span class="line"><span>├── 子 Agent 1（深度技术工作）→ 返回 ~1000-2000 token 的蒸馏摘要</span></span>
<span class="line"><span>├── 子 Agent 2（信息检索）→ 返回 ~1000-2000 token 的蒸馏摘要</span></span>
<span class="line"><span>└── 子 Agent 3（信息检索）→ 返回 ~1000-2000 token 的蒸馏摘要</span></span></code></pre></div><p>每个子 Agent 可能探索大量内容（数万个 token 或更多），但只返回压缩的蒸馏摘要（通常 1000-2000 token）。</p><h4 id="分离关注点" tabindex="-1">分离关注点 <a class="header-anchor" href="#分离关注点" aria-label="Permalink to &quot;分离关注点&quot;">​</a></h4><p>这种模式实现了清晰的关注点分离：</p><ul><li>详细搜索上下文保留在子 Agent 内部</li><li>主 Agent 专注于综合和分析结果</li></ul><h3 id="_5-4-三种技术的选择指南" tabindex="-1">5.4 三种技术的选择指南 <a class="header-anchor" href="#_5-4-三种技术的选择指南" aria-label="Permalink to &quot;5.4 三种技术的选择指南&quot;">​</a></h3><table tabindex="0"><thead><tr><th>任务特征</th><th>推荐技术</th></tr></thead><tbody><tr><td>需要大量来回对话</td><td>Compaction（保持对话流程）</td></tr><tr><td>有清晰里程碑的迭代开发</td><td>Note-taking（追踪进度和依赖）</td></tr><tr><td>复杂研究和分析，平行探索有回报</td><td>Multi-agent（并行探索）</td></tr></tbody></table><hr><h2 id="六、核心设计原则" tabindex="-1">六、核心设计原则 <a class="header-anchor" href="#六、核心设计原则" aria-label="Permalink to &quot;六、核心设计原则&quot;">​</a></h2><h3 id="_6-1-元原则" tabindex="-1">6.1 元原则 <a class="header-anchor" href="#_6-1-元原则" aria-label="Permalink to &quot;6.1 元原则&quot;">​</a></h3><blockquote><p><strong>找到最小的高信号 token 集合，以最大化期望结果的概率。</strong></p></blockquote><p>这是贯穿全文的元原则，无论处理系统提示、工具、示例还是长时域任务。</p><h3 id="_6-2-上下文工程的关键洞察" tabindex="-1">6.2 上下文工程的关键洞察 <a class="header-anchor" href="#_6-2-上下文工程的关键洞察" aria-label="Permalink to &quot;6.2 上下文工程的关键洞察&quot;">​</a></h3><ol><li><strong>上下文是迭代 curation</strong>，不是一次性编写</li><li><strong>注意力是有限预算</strong>，需要精心管理</li><li><strong>更聪明的模型 = 更少的规定性工程</strong>，更多自主性</li><li><strong>最简单的可行方案通常最优</strong>（Do the simplest thing that works）</li></ol><h3 id="_6-3-与传统软件工程的对比" tabindex="-1">6.3 与传统软件工程的对比 <a class="header-anchor" href="#_6-3-与传统软件工程的对比" aria-label="Permalink to &quot;6.3 与传统软件工程的对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>传统软件工程</th><th>上下文工程</th></tr></thead><tbody><tr><td>优化代码逻辑</td><td>优化信息选择</td></tr><tr><td>关注控制流</td><td>关注注意力分配</td></tr><tr><td>确定性执行</td><td>概率性引导</td></tr><tr><td>静态分析</td><td>动态适应</td></tr></tbody></table><hr><h2 id="七、对-ai-native-开发的启示" tabindex="-1">七、对 AI-Native 开发的启示 <a class="header-anchor" href="#七、对-ai-native-开发的启示" aria-label="Permalink to &quot;七、对 AI-Native 开发的启示&quot;">​</a></h2><h3 id="_7-1-从规则驱动到原则驱动" tabindex="-1">7.1 从规则驱动到原则驱动 <a class="header-anchor" href="#_7-1-从规则驱动到原则驱动" aria-label="Permalink to &quot;7.1 从规则驱动到原则驱动&quot;">​</a></h3><p>随着模型能力提升，Agent 设计趋势是：</p><ul><li>减少规定性规则</li><li>增加启发式原则</li><li>让智能模型更自主地行动</li></ul><h3 id="_7-2-信息设计的重要性" tabindex="-1">7.2 信息设计的重要性 <a class="header-anchor" href="#_7-2-信息设计的重要性" aria-label="Permalink to &quot;7.2 信息设计的重要性&quot;">​</a></h3><p>上下文工程的兴起意味着 AI 工程师需要越来越像<strong>信息架构师</strong>：</p><ul><li>思考什么信息应该在什么时候可用</li><li>设计信息的索引和检索机制</li><li>权衡信息的完整性和认知负荷</li></ul><h3 id="_7-3-与-model-context-protocol-mcp-的协同" tabindex="-1">7.3 与 Model Context Protocol (MCP) 的协同 <a class="header-anchor" href="#_7-3-与-model-context-protocol-mcp-的协同" aria-label="Permalink to &quot;7.3 与 Model Context Protocol (MCP) 的协同&quot;">​</a></h3><p>Anthropic 在文中提到 MCP（Model Context Protocol），这表明行业正在建立标准化的上下文管理协议。上下文工程不仅是个人实践，也正在成为系统级标准。</p><hr><h2 id="八、总结-上下文工程的核心框架" tabindex="-1">八、总结：上下文工程的核心框架 <a class="header-anchor" href="#八、总结-上下文工程的核心框架" aria-label="Permalink to &quot;八、总结：上下文工程的核心框架&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    上下文工程核心框架                             │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                                                                 │</span></span>
<span class="line"><span>│   问题: 如何在有限注意力预算下最大化期望行为概率？                │</span></span>
<span class="line"><span>│                                                                 │</span></span>
<span class="line"><span>│   方法:                                                             │</span></span>
<span class="line"><span>│   ├── 最小化: 用最小高信号 token 集                               │</span></span>
<span class="line"><span>│   ├── 结构化: 清晰分隔上下文的各组成部分                         │</span></span>
<span class="line"><span>│   ├── 动态化: Just-in-time 替代全量预加载                        │</span></span>
<span class="line"><span>│   ├── 持久化: 通过 compaction/note-taking 跨会话保持连贯性       │</span></span>
<span class="line"><span>│   └── 分层化: 多 Agent 架构分离关注点                            │</span></span>
<span class="line"><span>│                                                                 │</span></span>
<span class="line"><span>│   权衡:                                                             │</span></span>
<span class="line"><span>│   ├── 速度 vs 精度 (预检索 vs 运行时探索)                       │</span></span>
<span class="line"><span>│   ├── 完整性 vs 专注度 (全量 vs 精炼上下文)                     │</span></span>
<span class="line"><span>│   └── 自主性 vs 可控性 (探索 vs 规定)                            │</span></span>
<span class="line"><span>│                                                                 │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="九、延伸思考" tabindex="-1">九、延伸思考 <a class="header-anchor" href="#九、延伸思考" aria-label="Permalink to &quot;九、延伸思考&quot;">​</a></h2><h3 id="_9-1-为什么现在才提出上下文工程" tabindex="-1">9.1 为什么现在才提出上下文工程？ <a class="header-anchor" href="#_9-1-为什么现在才提出上下文工程" aria-label="Permalink to &quot;9.1 为什么现在才提出上下文工程？&quot;">​</a></h3><p>提示工程已经火热了几年，为什么上下文工程在当下这个时间点被明确提出？</p><p><strong>答案</strong>：Agent 范式的成熟。当 AI 应用从单轮任务转向多轮、长时域、工具使用的 Agent 系统时，上下文管理才成为核心挑战。</p><h3 id="_9-2-上下文工程-vs-rag" tabindex="-1">9.2 上下文工程 vs RAG <a class="header-anchor" href="#_9-2-上下文工程-vs-rag" aria-label="Permalink to &quot;9.2 上下文工程 vs RAG&quot;">​</a></h3><p>RAG（Retrieval-Augmented Generation）是预推理检索的一种实现，而上下文工程包含更广泛的策略：</p><ul><li>包括 Just-in-Time 检索</li><li>包括 Compaction、Note-taking 等非检索策略</li><li>包括如何组织、压缩、维护上下文</li></ul><p>RAG 是上下文工程的子集。</p><h3 id="_9-3-注意力预算的量化挑战" tabindex="-1">9.3 注意力预算的量化挑战 <a class="header-anchor" href="#_9-3-注意力预算的量化挑战" aria-label="Permalink to &quot;9.3 注意力预算的量化挑战&quot;">​</a></h3><p>虽然文章指出了注意力是有限预算，但目前我们还缺乏：</p><ul><li>量化特定信息&quot;消耗&quot;多少注意力预算的方法</li><li>预测上下文腐烂临界点的工具</li><li>自动优化上下文组成的系统</li></ul><p>这是一个值得深入研究的方向。</p><hr><h2 id="十、参考资料" tabindex="-1">十、参考资料 <a class="header-anchor" href="#十、参考资料" aria-label="Permalink to &quot;十、参考资料&quot;">​</a></h2><ul><li><a href="https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents" target="_blank" rel="noreferrer">Anthropic - Effective Context Engineering for AI Agents</a></li><li><a href="https://www.anthropic.com/research/building-effective-agents" target="_blank" rel="noreferrer">Anthropic - Building effective AI agents</a></li><li><a href="https://www.anthropic.com/engineering/writing-tools-for-agents" target="_blank" rel="noreferrer">Anthropic - Writing tools for AI agents</a></li><li><a href="https://research.trychroma.com/context-rot" target="_blank" rel="noreferrer">Context Rot Research</a></li><li><a href="https://modelcontextprotocol.io/docs/getting-started/intro" target="_blank" rel="noreferrer">Model Context Protocol</a></li><li><a href="https://simonwillison.net/2025/Sep/18/agents/" target="_blank" rel="noreferrer">Simon Willison - Agents Definition</a></li></ul><hr><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><ul><li>2026-04-12: 创建文档，完成深度分析</li></ul>`,158)])])}const m=a(r,[["render",i]]);export{q as __pageData,m as default};
